<script>
document.getElementById('unit-costs').addEventListener('submit', function (e) {
  e.preventDefault();
  var fd = new FormData(this); fd.append('action', 'save');
  SL.post('ajax/reports/message_costs_rates_ajax.php', fd).then(function (j) { var ok = j.ok !== false && !j.error; SL.toast(ok ? 'Prices saved' : (j.error || 'Not saved'), !ok); if (ok) setTimeout(function () { location.reload(); }, 400); });
});
</script>
